import 'dart:async';
import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'onboarding_backend.dart';

const _bg = Color(0xFF07111F);
const _panel = Color(0xFF101A30);
const _purple = Color(0xFF8B5CFF);
const _muted = Color(0xFFA7B0C7);
const _danger = Color(0xFFFF4D63);

class OwnerChatPage extends StatefulWidget {
  const OwnerChatPage({super.key, required this.notificationId, required this.plate});
  final String notificationId;
  final String plate;
  @override State<OwnerChatPage> createState()=>_OwnerChatPageState();
}

class _OwnerChatPageState extends State<OwnerChatPage>{
  static const baseUrl='https://heycar-api-185-165-46-213.nip.io';
  final input=TextEditingController(); final scroll=ScrollController();
  List<Map<String,dynamic>> messages=[]; String? conversationId; String? error; bool loading=true,sending=false,blocked=false; Timer? timer;
  @override void initState(){super.initState();_resolve();}
  @override void dispose(){timer?.cancel();input.dispose();scroll.dispose();super.dispose();}
  void _scrollToBottom(){WidgetsBinding.instance.addPostFrameCallback((_){if(!mounted||!scroll.hasClients)return;scroll.animateTo(scroll.position.maxScrollExtent,duration:const Duration(milliseconds:220),curve:Curves.easeOut);});}
  Future<void> _resolve()async{final ownerId=OnboardingDraft.userId.trim();if(ownerId.isEmpty){if(mounted)setState((){loading=false;error='Araç sahibi oturumu bulunamadı.';});return;}if(mounted)setState((){loading=true;error=null;});try{final r=await http.get(Uri.parse('$baseUrl/api/owner/notifications/${Uri.encodeComponent(widget.notificationId)}/conversation'),headers:{'x-owner-id':ownerId}).timeout(const Duration(seconds:15));if(r.statusCode<200||r.statusCode>=300)throw Exception();final d=jsonDecode(r.body)as Map<String,dynamic>;final id=d['conversationId']?.toString()??'';if(id.isEmpty)throw Exception();conversationId=id;blocked=d['status']?.toString()=='blocked';await _load();timer?.cancel();if(!blocked)timer=Timer.periodic(const Duration(seconds:3),(_)=>_load(silent:true));}catch(_){if(mounted)setState((){loading=false;error='Sohbet açılamadı. Tekrar dene.';});}}
  Future<void> _load({bool silent=false})async{final id=conversationId;if(id==null||id.isEmpty)return;try{final r=await http.get(Uri.parse('$baseUrl/api/owner/conversations/${Uri.encodeComponent(id)}'),headers:{'x-owner-id':OnboardingDraft.userId.trim()}).timeout(const Duration(seconds:15));if(r.statusCode<200||r.statusCode>=300)throw Exception();final d=jsonDecode(r.body)as Map<String,dynamic>;final list=d['messages'];if(list is! List)throw Exception();final next=list.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();if(!mounted)return;final changed=next.length!=messages.length||(next.isNotEmpty&&messages.isNotEmpty&&next.last['id']?.toString()!=messages.last['id']?.toString());setState((){messages=next;blocked=d['status']?.toString()=='blocked';loading=false;error=null;});if(blocked)timer?.cancel();if(changed)_scrollToBottom();}catch(_){if(!silent&&mounted)setState((){loading=false;error='Mesajlar yüklenemedi. Tekrar dene.';});}}
  Future<void> _send()async{final id=conversationId,text=input.text.trim();if(id==null||id.isEmpty||text.isEmpty||sending||blocked)return;setState(()=>sending=true);try{final r=await http.post(Uri.parse('$baseUrl/api/owner/conversations/${Uri.encodeComponent(id)}/messages'),headers:{'Content-Type':'application/json','x-owner-id':OnboardingDraft.userId.trim()},body:jsonEncode({'message':text})).timeout(const Duration(seconds:15));if(r.statusCode<200||r.statusCode>=300)throw Exception();input.clear();await _load();_scrollToBottom();}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Mesaj gönderilemedi. Tekrar dene.')));}finally{if(mounted)setState(()=>sending=false);}}
  Future<void> _block()async{final id=conversationId;if(id==null||blocked)return;final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(backgroundColor:_panel,title:const Text('Oturumu engelle?',style:TextStyle(color:Colors.white,fontWeight:FontWeight.w900)),content:const Text('Bu tarama oturumu anında kapanır. QR etiketiniz değişmez ve diğer kişiler QR’ı kullanmaya devam edebilir.',style:TextStyle(color:_muted,height:1.35)),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Vazgeç')),FilledButton(style:FilledButton.styleFrom(backgroundColor:_danger),onPressed:()=>Navigator.pop(c,true),child:const Text('Engelle'))]));if(ok!=true)return;try{final r=await http.post(Uri.parse('$baseUrl/api/owner/conversations/${Uri.encodeComponent(id)}/block'),headers:{'x-owner-id':OnboardingDraft.userId.trim()}).timeout(const Duration(seconds:15));if(r.statusCode<200||r.statusCode>=300)throw Exception();timer?.cancel();if(mounted){setState(()=>blocked=true);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Tarama oturumu engellendi. QR etiketiniz değişmedi.')));}}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Oturum engellenemedi. Tekrar dene.')));}}
  @override Widget build(BuildContext context)=>Scaffold(backgroundColor:_bg,appBar:AppBar(backgroundColor:_bg,foregroundColor:Colors.white,title:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.plate.isEmpty?'Anonim Sohbet':widget.plate,style:const TextStyle(fontWeight:FontWeight.w900)),Text(blocked?'Oturum engellendi':'Kimlik bilgileri karşılıklı gizlidir',style:TextStyle(color:blocked?_danger:_muted,fontSize:11))]),actions:[if(!loading&&!blocked&&conversationId!=null)IconButton(tooltip:'Oturumu Engelle',onPressed:_block,icon:const Icon(Icons.block_rounded,color:_danger))]),body:loading?const Center(child:CircularProgressIndicator(color:_purple)):error!=null?Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.chat_bubble_outline_rounded,color:_muted,size:42),const SizedBox(height:10),Text(error!,textAlign:TextAlign.center,style:const TextStyle(color:_muted)),const SizedBox(height:12),FilledButton(onPressed:_resolve,style:FilledButton.styleFrom(backgroundColor:_purple),child:const Text('Tekrar dene'))])):Column(children:[if(blocked)Container(width:double.infinity,padding:const EdgeInsets.symmetric(horizontal:16,vertical:11),color:const Color(0x22FF4D63),child:const Row(children:[Icon(Icons.block_rounded,color:_danger,size:19),SizedBox(width:8),Expanded(child:Text('Bu tarama oturumu engellendi. Yeni mesaj gönderilemez.',style:TextStyle(color:_danger,fontSize:12.5,fontWeight:FontWeight.w800)))])),Expanded(child:ListView.builder(controller:scroll,padding:const EdgeInsets.all(16),itemCount:messages.length,itemBuilder:(_,i){final m=messages[i],mine=m['sender']?.toString()=='owner';return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:const BoxConstraints(maxWidth:300),margin:const EdgeInsets.only(bottom:9),padding:const EdgeInsets.symmetric(horizontal:14,vertical:11),decoration:BoxDecoration(color:mine?_purple:_panel,borderRadius:BorderRadius.only(topLeft:const Radius.circular(18),topRight:const Radius.circular(18),bottomLeft:Radius.circular(mine?18:4),bottomRight:Radius.circular(mine?4:18))),child:Text(m['message']?.toString()??'',style:const TextStyle(color:Colors.white,height:1.3))));})),if(!blocked)SafeArea(top:false,child:Container(padding:const EdgeInsets.fromLTRB(12,10,12,12),color:const Color(0xFF0B1426),child:Row(children:[Expanded(child:TextField(controller:input,style:const TextStyle(color:Colors.white),decoration:InputDecoration(hintText:'Mesaj yaz...',hintStyle:const TextStyle(color:_muted),filled:true,fillColor:_panel,border:OutlineInputBorder(borderRadius:BorderRadius.circular(22),borderSide:BorderSide.none)),onSubmitted:(_)=>_send())),const SizedBox(width:8),IconButton.filled(onPressed:sending?null:_send,style:IconButton.styleFrom(backgroundColor:_purple),icon:sending?const SizedBox(width:20,height:20,child:CircularProgressIndicator(color:Colors.white,strokeWidth:2)):const Icon(Icons.send_rounded))])))]));
}
